    public class NeuralNetwork 
    {
        int inputs, hiddenNodes, outputs;
        double[][] hiddenWeights;
        double[] hiddenBiases, outputWeights, outputBiases;

        public NeuralNetwork(int _inputs, int _hiidenNodes, int _outputs)
        {
            inputs = _inputs;
            hiddenNodes = _hiidenNodes;
            outputs = _outputs;
        }

        public double ForwardPropogate(double[] inputs)
        {
            double[] hiddenOutputs = HiddenLayer(inputs, hiddenWeights, hiddenBiases);

            double output = OutputLayer(hiddenOutputs, outputWeights, outputBiases);

            return output;
        }

        double[] HiddenLayer(double[] inputs, double[][] weights, double[] biases)
        {
            double[] outputs = new double[hiddenNodes];
            for (int i = 0; i < hiddenNodes; i++)
            {
                double sum = biases[i];
                for (int j = 0; j < inputs.Length; j++)
                {
                    sum += inputs[j] * weights[j][i];
                }
                outputs[i] = sum;
            }
            return outputs;
        }

        double OutputLayer(double[] hiddenOutputs, double[] weights, double[] bias)
        {
            double sum = 0;
            for (int i = 0; i < hiddenOutputs.Length; i++)
            {
                sum += hiddenOutputs[i] * weights[i];
            }
            sum += bias[0];
            return sum;
        }
    }
}

